    const backend = new SoftwareRenderBackend();
    backend.init({ width: 8, height: 8 });
    backend.drawFrame(sceneGraph([node({ layerId: "a" })]));
    backend.drawFrame(sceneGraph([]));
    expect(backend.getFramebuffer()[3]).toBe(0);
  });
