27	/**
28	 * Converts one full-range YUV sample (Y/U/V each 0-255, U/V centered at
29	 * 128) to RGB (each 0-255) using the given standard's matrix. WebCodecs'
30	 * `VideoFrame` reports its own matrix via `colorSpace.matrix` — pass
31	 * `"bt601"` for `"smpte170m"`/`"bt470bg"` and `"bt709"` for `"bt709"`
32	 * (the common case for HD web video).
33	 */
34	export function yuvToRgb(
35	  y: number,
36	  u: number,
37	  v: number,
38	  standard: ColorMatrixStandard = "bt709",
39	): [number, number, number] {
40	  const { kr, kb } = COEFFICIENTS[standard];
41	  const kg = 1 - kr - kb;
42	  const uCentered = u - 128;
43	  const vCentered = v - 128;
44	
45	  const r = y + 2 * (1 - kr) * vCentered;
46	  const b = y + 2 * (1 - kb) * uCentered;
47	  const g = y - (2 * kr * (1 - kr) * vCentered + 2 * kb * (1 - kb) * uCentered) / kg;

